/*
 * NEW YEAR / CONCEPT 09 / AROUND THE WORLD NEW YEAR
 * Pure Canvas 2D. One scene. Seamless 20-second loop. Time is in seconds.
 * Video encoder target: 100,000,000 bit/s; set in the export application.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * sceneProgress;
  const C = {
    green: '#00FF00', ink: '#202A43', navy: '#293853', navyLight: '#40516D',
    cream: '#FFF1D5', paper: '#FFF9EB', gold: '#EDBB58', goldLight: '#FFDA89',
    ochre: '#BE843B', coral: '#E97D70', blue: '#6E91BA', magenta: '#BD6386'
  };
  function smooth(v) {
    const q = Math.max(0, Math.min(1, v));
    return q * q * q * (10 + q * (-15 + 6 * q));
  }
  function pulse(start, riseEnd, fallStart, end) {
    return smooth((loopT - start) / (riseEnd - start))
      * (1 - smooth((loopT - fallStart) / (end - fallStart)));
  }
  function roundRect(x, y, w, h, r, fill, stroke, lw) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath(); ctx.moveTo(x + q, y); ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q); ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h); ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q); ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y); ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 4; ctx.stroke(); }
  }
  function ellipse(x, y, rx, ry, fill, stroke, lw) {
    ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 4; ctx.stroke(); }
  }
  function line(x1, y1, x2, y2, color, lw) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
  }
  function text(label, x, y, size, maxWidth, color, weight) {
    ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    ctx.font = (weight || '700') + ' ' + size + 'px Arial, "DejaVu Sans", sans-serif';
    const measured = ctx.measureText(label).width;
    if (measured > maxWidth) {
      size *= maxWidth / measured;
      ctx.font = (weight || '700') + ' ' + size + 'px Arial, "DejaVu Sans", sans-serif';
    }
    const m = ctx.measureText(label);
    const dy = m.actualBoundingBoxAscent === undefined ? size * 0.34
      : (m.actualBoundingBoxAscent - m.actualBoundingBoxDescent) / 2;
    ctx.fillStyle = color; ctx.fillText(label, x, y + dy);
  }
  function starPath(r, inner) {
    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
      const a = -Math.PI / 2 + i * Math.PI / 5;
      const rr = i % 2 ? r * inner : r;
      if (i === 0) ctx.moveTo(Math.cos(a) * rr, Math.sin(a) * rr);
      else ctx.lineTo(Math.cos(a) * rr, Math.sin(a) * rr);
    }
    ctx.closePath();
  }
  function star(x, y, r, color, angle) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle || 0); starPath(r, 0.46);
    ctx.fillStyle = color; ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 3.5;
    ctx.stroke(); ctx.restore();
  }
  function curl(x, y, direction, size, angle, color) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle); ctx.scale(direction * size, size);
    ctx.beginPath(); ctx.moveTo(2, 45);
    ctx.bezierCurveTo(-21, 31, -20, 5, 4, -7);
    ctx.bezierCurveTo(30, -19, 25, -44, 4, -48);
    ctx.bezierCurveTo(-10, -51, -21, -41, -15, -30);
    ctx.strokeStyle = C.ink; ctx.lineWidth = 8; ctx.stroke();
    ctx.strokeStyle = color; ctx.lineWidth = 4; ctx.stroke(); ctx.restore();
  }
  function polygon(points, fill, stroke, lw) {
    ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);
    for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);
    ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw||4;ctx.stroke();}
  }
  function ribbon(label, y, w, size) {
    const left=960-w/2,right=960+w/2;
    polygon([[left,y+12],[left-49,y+12],[left-33,y+36],[left-49,y+61],[left,y+61]],C.coral,C.ink,4);
    polygon([[right,y+12],[right+49,y+12],[right+33,y+36],[right+49,y+61],[right,y+61]],C.coral,C.ink,4);
    roundRect(left,y,w,73,10,C.cream,C.ink,4.5);
    text(label,960,y+37,size,w-58,C.navy,'800');
  }
  const globeY=480+3*Math.sin(phase),globeR=222;
  const orbitAngle=-0.26,theta=phase-Math.PI/2;
  function orbitPoint(a) {
    const x=350*Math.cos(a),y=128*Math.sin(a),c=Math.cos(orbitAngle),s=Math.sin(orbitAngle);
    return {x:960+x*c-y*s,y:globeY+x*s+y*c,
      angle:Math.atan2(-350*Math.sin(a)*s+128*Math.cos(a)*c,
        -350*Math.sin(a)*c-128*Math.cos(a)*s)};
  }
  function flightPath(front) {
    ctx.save();ctx.translate(960,globeY);ctx.rotate(orbitAngle);
    ctx.beginPath();ctx.ellipse(0,0,350,128,0,front?0:Math.PI,front?Math.PI:TAU);
    ctx.strokeStyle=front?C.gold:C.navyLight;ctx.lineWidth=front?4:3;
    if(!front)ctx.setLineDash([9,12]);ctx.stroke();ctx.restore();
  }
  function aircraft(pose) {
    ctx.save();ctx.translate(pose.x,pose.y);ctx.rotate(pose.angle);
    // The exterior contour joins both wings and tail into one precise silhouette.
    ctx.beginPath();ctx.moveTo(52,0);
    ctx.bezierCurveTo(48,-5,36,-7,19,-7);
    ctx.lineTo(-2,-37);ctx.lineTo(-17,-37);ctx.lineTo(-6,-6);
    ctx.lineTo(-32,-5);ctx.lineTo(-43,-17);ctx.lineTo(-51,-17);
    ctx.lineTo(-46,0);ctx.lineTo(-51,17);ctx.lineTo(-43,17);
    ctx.lineTo(-32,5);ctx.lineTo(-6,6);ctx.lineTo(-17,37);
    ctx.lineTo(-2,37);ctx.lineTo(19,7);ctx.bezierCurveTo(36,7,48,5,52,0);ctx.closePath();
    ctx.fillStyle=C.paper;ctx.fill();ctx.strokeStyle=C.ink;ctx.lineWidth=3.5;ctx.stroke();
    line(-27,0,22,0,C.gold,3);
    line(-4,-27,7,-8,C.blue,2);line(-4,27,7,8,C.blue,2);
    polygon([[33,-4],[40,-3],[42,0],[40,3],[33,4],[35,0]],C.navy,null);
    line(-43,-11,-38,-6,C.coral,3);line(-43,11,-38,6,C.coral,3);
    ctx.restore();
  }
  function continent(points) {
    polygon(points,C.cream,C.ink,2.6);
  }
  function globe() {
    ctx.save();ctx.translate(960,globeY);
    ellipse(0,0,globeR,globeR,C.blue,C.ink,5);
    ctx.save();ctx.beginPath();ctx.arc(0,0,globeR-1,0,TAU);ctx.clip();
    for(let i=-1;i<=1;i++){
      const yy=i*91,rx=Math.sqrt(globeR*globeR-yy*yy);
      ellipse(0,yy,rx,30,null,C.navyLight,1.8);
    }
    ellipse(0,0,73,globeR,null,C.navyLight,1.8);
    ellipse(0,0,156,globeR,null,C.navyLight,1.8);
    // Original, simplified continent contours; all coordinates share the globe origin.
    continent([[-211,-65],[-190,-112],[-169,-141],[-128,-154],[-99,-140],[-78,-142],
      [-59,-117],[-76,-96],[-73,-74],[-100,-66],[-108,-39],[-133,-26],[-142,-2],
      [-155,-13],[-160,-42],[-183,-47],[-192,-63]]);
    continent([[-137,12],[-113,10],[-90,28],[-72,41],[-63,69],[-75,98],
      [-83,110],[-83,139],[-100,166],[-110,153],[-116,123],[-128,99],
      [-130,67],[-145,42]]);
    continent([[-104,-181],[-79,-198],[-52,-189],[-46,-170],[-65,-151],[-87,-155]]);
    continent([[-13,-139],[7,-161],[41,-160],[58,-179],[87,-174],[101,-148],
      [130,-145],[143,-121],[175,-119],[202,-84],[205,-52],[176,-36],[160,-7],
      [133,-23],[119,-4],[107,-22],[83,-36],[64,-60],[41,-68],[29,-92],
      [7,-92],[-5,-113],[-23,-112]]);
    continent([[-12,-70],[20,-79],[47,-62],[61,-32],[69,-2],[50,22],[43,53],
      [22,85],[7,99],[-11,73],[-19,46],[-38,22],[-40,-8],[-25,-29],[-28,-51]]);
    continent([[129,93],[158,81],[181,99],[185,126],[164,145],[139,139],[119,116]]);
    continent([[90,20],[104,34],[101,58],[90,54],[83,37]]);
    ctx.restore();ellipse(0,0,globeR,globeR,null,C.ink,5);ctx.restore();
  }
  function locationPin(x,y,index) {
    const envelopes=[pulse(0.5,1.6,2.6,4),pulse(10,10.8,11.4,12.2),pulse(12.3,13.1,13.7,14.5)];
    const s=1+0.035*envelopes[index];
    ctx.save();ctx.translate(960+x,globeY+y);ctx.scale(s,s);
    polygon([[-6,8],[0,20],[6,8]],C.coral,C.ink,2.5);
    ellipse(0,-2,17,17,C.paper,C.ink,3);
    star(0,-2,8.7,C.gold,0);ctx.restore();
  }
  function building(x,ground,w,h,color,cols,rows) {
    roundRect(x,ground-h,w,h,3,color,C.ink,3.5);
    const gapX=w/(cols+1),gapY=(h-22)/(rows+1);
    for(let row=0;row<rows;row++)for(let col=0;col<cols;col++)
      roundRect(x+gapX*(col+1)-4,ground-h+14+gapY*(row+1)-4,8,8,1,
        color===C.cream?C.blue:C.cream,null);
  }
  function cityCluster(x,kind) {
    ctx.save();ctx.translate(x,0);
    const ground=877;
    if(kind===0) {
      building(-112,ground,57,93,C.blue,2,3);
      building(-37,ground,72,126,C.cream,3,4);
      polygon([[-43,751],[-1,724],[41,751]],C.coral,C.ink,3.5);
      building(52,ground,57,77,C.navyLight,2,2);
    } else if(kind===1) {
      building(-111,ground,61,98,C.cream,2,3);
      building(-32,ground,67,117,C.blue,2,4);
      roundRect(-23,745,49,18,3,C.coral,C.ink,3);
      building(54,ground,57,83,C.navyLight,2,3);
    } else {
      building(-113,ground,58,81,C.blue,2,3);
      building(-37,ground,73,132,C.navyLight,3,4);
      roundRect(-24,731,47,16,3,C.gold,C.ink,3);
      building(54,ground,58,98,C.cream,2,3);
    }
    roundRect(-127,873,254,14,5,C.gold,C.ink,3.5);ctx.restore();
  }

  ctx.save();ctx.setTransform(1,0,0,1,0,0);
  ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';ctx.filter='none';
  ctx.setLineDash([]);ctx.lineDashOffset=0;
  ctx.shadowBlur=0;ctx.shadowOffsetX=0;ctx.shadowOffsetY=0;ctx.shadowColor='transparent';
  ctx.fillStyle=C.green;ctx.fillRect(0,0,width,height);
  ctx.translate(width/2,height/2);ctx.scale(scale,scale);ctx.translate(-960,-540);
  ctx.lineCap='round';ctx.lineJoin='round';ctx.miterLimit=2;
  if(currentScene===0) {
    ribbon('NEW YEAR AROUND THE WORLD',132,690,30);
    star(315+3*Math.sin(phase),286+4*Math.cos(phase),23,C.gold,-0.1);
    star(1605-3*Math.sin(phase),290-4*Math.cos(phase),23,C.coral,0.1);
    curl(326,489,-1,0.75,0.03*Math.sin(phase),C.coral);
    curl(1594,489,1,0.75,-0.03*Math.sin(phase),C.gold);
    const planePose=orbitPoint(theta),front=Math.sin(theta)>=0;
    flightPath(false);if(!front)aircraft(planePose);globe();
    flightPath(true);
    locationPin(-130,-70,0);locationPin(84,-105,1);locationPin(10,20,2);
    if(front)aircraft(planePose);
    roundRect(230,889,1460,73,14,C.navy,C.ink,4.5);
    roundRect(230,875,1460,26,9,C.cream,C.ink,4.5);
    cityCluster(410,0);cityCluster(960,1);cityCluster(1510,2);
    text('ONE WORLD, A NEW BEGINNING',960,933,27,790,C.cream,'800');
    line(288,932,420,932,C.gold,3);line(1500,932,1632,932,C.gold,3);
  }
  ctx.restore();
}

/*
 * NEW YEAR / CONCEPT 10 / NEW YEAR GOALS LAUNCHPAD
 * Pure Canvas 2D. One scene. Seamless 20-second loop. Time is in seconds.
 * Video encoder target: 100,000,000 bit/s; set in the export application.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * sceneProgress;
  const C = {
    green: '#00FF00', ink: '#202A43', navy: '#293853', navyLight: '#40516D',
    cream: '#FFF1D5', paper: '#FFF9EB', gold: '#EDBB58', goldLight: '#FFDA89',
    ochre: '#BE843B', coral: '#E97D70', blue: '#6E91BA', magenta: '#BD6386'
  };
  function smooth(v) {
    const q = Math.max(0, Math.min(1, v));
    return q * q * q * (10 + q * (-15 + 6 * q));
  }
  function pulse(start, riseEnd, fallStart, end) {
    return smooth((loopT - start) / (riseEnd - start))
      * (1 - smooth((loopT - fallStart) / (end - fallStart)));
  }
  function roundRect(x, y, w, h, r, fill, stroke, lw) {
    const q = Math.min(r, w / 2, h / 2);
    ctx.beginPath(); ctx.moveTo(x + q, y); ctx.lineTo(x + w - q, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + q); ctx.lineTo(x + w, y + h - q);
    ctx.quadraticCurveTo(x + w, y + h, x + w - q, y + h); ctx.lineTo(x + q, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - q); ctx.lineTo(x, y + q);
    ctx.quadraticCurveTo(x, y, x + q, y); ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 4; ctx.stroke(); }
  }
  function ellipse(x, y, rx, ry, fill, stroke, lw) {
    ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 4; ctx.stroke(); }
  }
  function line(x1, y1, x2, y2, color, lw) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = lw; ctx.stroke();
  }
  function text(label, x, y, size, maxWidth, color, weight) {
    ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    ctx.font = (weight || '700') + ' ' + size + 'px Arial, "DejaVu Sans", sans-serif';
    const measured = ctx.measureText(label).width;
    if (measured > maxWidth) {
      size *= maxWidth / measured;
      ctx.font = (weight || '700') + ' ' + size + 'px Arial, "DejaVu Sans", sans-serif';
    }
    const m = ctx.measureText(label);
    const dy = m.actualBoundingBoxAscent === undefined ? size * 0.34
      : (m.actualBoundingBoxAscent - m.actualBoundingBoxDescent) / 2;
    ctx.fillStyle = color; ctx.fillText(label, x, y + dy);
  }
  function starPath(r, inner) {
    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
      const a = -Math.PI / 2 + i * Math.PI / 5;
      const rr = i % 2 ? r * inner : r;
      if (i === 0) ctx.moveTo(Math.cos(a) * rr, Math.sin(a) * rr);
      else ctx.lineTo(Math.cos(a) * rr, Math.sin(a) * rr);
    }
    ctx.closePath();
  }
  function star(x, y, r, color, angle) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle || 0); starPath(r, 0.46);
    ctx.fillStyle = color; ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 3.5;
    ctx.stroke(); ctx.restore();
  }
  function curl(x, y, direction, size, angle, color) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(angle); ctx.scale(direction * size, size);
    ctx.beginPath(); ctx.moveTo(2, 45);
    ctx.bezierCurveTo(-21, 31, -20, 5, 4, -7);
    ctx.bezierCurveTo(30, -19, 25, -44, 4, -48);
    ctx.bezierCurveTo(-10, -51, -21, -41, -15, -30);
    ctx.strokeStyle = C.ink; ctx.lineWidth = 8; ctx.stroke();
    ctx.strokeStyle = color; ctx.lineWidth = 4; ctx.stroke(); ctx.restore();
  }
  function polygon(points, fill, stroke, lw) {
    ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);
    for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);
    ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw||4;ctx.stroke();}
  }
  function ribbon(label, y, w, size) {
    const left=960-w/2,right=960+w/2;
    polygon([[left,y+12],[left-49,y+12],[left-33,y+36],[left-49,y+61],[left,y+61]],C.coral,C.ink,4);
    polygon([[right,y+12],[right+49,y+12],[right+33,y+36],[right+49,y+61],[right,y+61]],C.coral,C.ink,4);
