  }
  const flight=pulse(5,10,15,19);
  const rocketY=834-230*flight+2.5*Math.sin(phase*2)*flight;
  function rocketBodyPath() {
    ctx.beginPath();ctx.moveTo(0,-292);
    ctx.bezierCurveTo(-30,-267,-58,-231,-58,-208);ctx.lineTo(-58,-56);
    ctx.bezierCurveTo(-58,-39,-43,-28,-29,-28);ctx.lineTo(29,-28);
    ctx.bezierCurveTo(43,-28,58,-39,58,-56);ctx.lineTo(58,-208);
    ctx.bezierCurveTo(58,-231,30,-267,0,-292);ctx.closePath();
  }
  function flame() {
    ctx.save();ctx.translate(960,rocketY);
    const s=0.78+0.12*flight+0.065*Math.sin(phase*10);
    ctx.scale(s,s);
    ctx.beginPath();ctx.moveTo(-23,0);ctx.lineTo(23,0);
    ctx.bezierCurveTo(24,18,13,42,0,54);
    ctx.bezierCurveTo(-13,42,-24,18,-23,0);ctx.closePath();
    ctx.fillStyle=C.gold;ctx.fill();ctx.strokeStyle=C.ink;ctx.lineWidth=3.5;ctx.stroke();
    ctx.beginPath();ctx.moveTo(-10,2);ctx.lineTo(10,2);
    ctx.bezierCurveTo(11,13,6,26,0,33);ctx.bezierCurveTo(-6,26,-11,13,-10,2);ctx.closePath();
    ctx.fillStyle=C.cream;ctx.fill();ctx.restore();
  }
  function rocket() {
    ctx.save();ctx.translate(960,rocketY);
    // Fins, engine and body share this rigid frame throughout lift and landing.
    for(let side=-1;side<=1;side+=2) {
      ctx.save();ctx.scale(side,1);
      ctx.beginPath();ctx.moveTo(43,-111);
      ctx.quadraticCurveTo(96,-89,105,4);ctx.lineTo(65,4);ctx.lineTo(45,-56);ctx.closePath();
      ctx.fillStyle=C.coral;ctx.fill();ctx.strokeStyle=C.ink;ctx.lineWidth=4.5;ctx.stroke();
      line(72,-38,92,-8,C.cream,3);ctx.restore();
    }
    polygon([[-29,-31],[29,-31],[36,-1],[-36,-1]],C.navy,C.ink,4);
    line(-23,-12,23,-12,C.gold,3);
    rocketBodyPath();ctx.fillStyle=C.paper;ctx.fill();
    ctx.save();rocketBodyPath();ctx.clip();
    ctx.fillStyle=C.coral;ctx.fillRect(-65,-300,130,92);
    line(-60,-208,60,-208,C.ink,3);
    roundRect(-60,-86,120,14,1,C.gold,C.ink,2.5);ctx.restore();
    rocketBodyPath();ctx.strokeStyle=C.ink;ctx.lineWidth=4.5;ctx.stroke();
    ellipse(0,-157,38,38,C.gold,C.ink,4);
    ellipse(0,-157,27,27,C.blue,C.ink,3.5);
    ctx.beginPath();ctx.arc(0,-157,18,-2.8,-1.9);
    ctx.strokeStyle=C.cream;ctx.lineWidth=3;ctx.stroke();
    for(let i=0;i<4;i++) {
      const a=i*Math.PI/2;
      ellipse(32*Math.cos(a),-157+32*Math.sin(a),2.3,2.3,C.ink,null);
    }
    line(-15,-115,15,-115,C.navy,3);
    ctx.restore();
  }
  function launchPlatform() {
    roundRect(837,879,36,53,6,C.navy,C.ink,4);
    roundRect(1047,879,36,53,6,C.navy,C.ink,4);
    ctx.beginPath();ctx.moveTo(798,838);ctx.lineTo(798,876);
    ctx.bezierCurveTo(798,902,1122,902,1122,876);ctx.lineTo(1122,838);ctx.closePath();
    ctx.fillStyle=C.navy;ctx.fill();ctx.strokeStyle=C.ink;ctx.lineWidth=4.5;ctx.stroke();
    ellipse(960,838,162,20,C.cream,C.ink,4.5);
